package pe.edu.magistra.dao.impl; import pe.edu.magistra.dao.TemaDAO; import pe.edu.magistra.model.Tema; import pe.edu.magistra.util.ConexionBD; import java.sql.*; import java.util.*;
public class TemaDAOImpl implements TemaDAO{private Tema m(ResultSet r)throws SQLException{return new Tema(r.getInt(1),r.getInt(2),r.getString(3),r.getString(4),r.getBoolean(5));} public List<Tema> listarPorCategoria(int cat)throws Exception{List<Tema>l=new ArrayList<>();try(Connection c=ConexionBD.getConexion();PreparedStatement p=c.prepareStatement("SELECT id_tema,id_categoria,nombre,descripcion,estado FROM temas WHERE id_categoria=? AND estado=1 ORDER BY nombre")){p.setInt(1,cat);try(ResultSet r=p.executeQuery()){while(r.next())l.add(m(r));}}return l;} public List<Tema> listar()throws Exception{List<Tema>l=new ArrayList<>();try(Connection c=ConexionBD.getConexion();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id_tema,id_categoria,nombre,descripcion,estado FROM temas WHERE estado=1")){while(r.next())l.add(m(r));}return l;} public Optional<Tema> buscarPorId(long id)throws Exception{try(Connection c=ConexionBD.getConexion();PreparedStatement p=c.prepareStatement("SELECT id_tema,id_categoria,nombre,descripcion,estado FROM temas WHERE id_tema=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(m(r)):Optional.empty();}}} public boolean insertar(Tema o){throw new UnsupportedOperationException();} public boolean actualizar(Tema o){throw new UnsupportedOperationException();} public boolean eliminar(long id){throw new UnsupportedOperationException();}}
